{
  "category_edits": [
    {
      "category": "sequence_modeling",
      "rationale": "Halve the maximum causal context, rounding up with a minimum of two interactions, to reduce stale-history interference and recurrent computation. Existing truncation retains recent events chronologically. Saved maxlen metadata applies the same context limit in the generated predictor, preserving the GRU, embeddings, readout, loss, optimizer, and category routing.",
      "edits": [
        {
          "find": "MAXLEN        = int(os.environ.get(\"GRU4REC_MAXLEN\", \"128\"))",
          "replace": "MAXLEN        = max(2, (int(os.environ.get(\"GRU4REC_MAXLEN\", \"128\")) + 1) // 2)"
        }
      ]
    }
  ],
  "change_summary": "Reduce default causal context from 128 to 64 interactions consistently across training, validation, and metadata-driven prediction."
}
